import {
  base,
  baseSepolia,
  mainnet,
  polygon,
  sepolia,
  type Chain,
} from 'viem/chains';

// Chains we care about right now. Add more as needed.
// We rely on viem's bundled `blockExplorers.default.url` so we don't have to
// hand-maintain explorer URLs.
const KNOWN_CHAINS: readonly Chain[] = [
  base,
  baseSepolia,
  mainnet,
  polygon,
  sepolia,
];

export function getChainName(chainId: number | undefined): string | null {
  if (!chainId) return null;
  return KNOWN_CHAINS.find((c) => c.id === chainId)?.name ?? null;
}

export function getAddressExplorerUrl(
  chainId: number | undefined,
  address: string | undefined
): string | null {
  if (!chainId || !address) return null;
  const url = KNOWN_CHAINS.find((c) => c.id === chainId)?.blockExplorers
    ?.default?.url;
  return url ? `${url}/address/${address}` : null;
}
=== src/lib/error-reporting.ts ===
'use client';

import * as Sentry from '@sentry/nextjs';

type Severity = 'fatal' | 'error' | 'warning' | 'info';

interface ReportOptions {
  area: 'auth' | 'wallet' | 'openfort' | 'telemetry' | 'unknown';
  severity?: Severity;
  tags?: Record<string, string>;
  extra?: Record<string, unknown>;
  fingerprint?: string[];
}

export function isNoisyNetworkError(message: string | undefined | null) {
  if (!message) return false;
  return /failed to fetch|networkerror|load failed|analytics sdk/i.test(
    message
  );
}

export function reportError(error: unknown, options: ReportOptions) {
  const severity = options.severity ?? 'error';

  if (error instanceof Error && isNoisyNetworkError(error.message)) {
    Sentry.addBreadcrumb({
      category: options.area,
      message: error.message,
      level: 'warning',
      data: { ...options.extra },
    });
    return;
  }

  Sentry.captureException(error, {
    level: severity,
    tags: {
      area: options.area,
      ...options.tags,
    },
    extra: options.extra,
    fingerprint: options.fingerprint,
  });
}
