  query: string;
  offset: number;
  limit: number;
}) {
  const countries = await listCountries(options);

  return {
    items: countries.map((country) => ({
      ID: country.id,
      Name: country.name,
      Iso: country.iso,
      Iso3: country.iso3,
      Code: country.code,
      PhoneCode: country.phoneCode,
    })),
  };
}

