24	          <Script
25	            src={`https://www.google.com/recaptcha/api.js?render=${recaptchaSiteKey}`}
26	            strategy="afterInteractive"
27	          />
28	        ) : null}
29	        <AppProviders>
30	          <MainLayout>{children}</MainLayout>
