1	'use client';
2	
3	import { useState, useRef, useEffect, useLayoutEffect } from 'react';
4	import { createPortal } from 'react-dom';
5	
6	interface DropdownOption {
7	  key: string;
8	  label: string;
9	  value: string;
10	}
11	
12	interface DropdownProps {
13	  options: DropdownOption[];
14	  value?: string;
15	  onChange?: (value: string, key: string) => void;
16	  placeholder?: string;
17	  label?: string;
18	  className?: string;
19	}
20	
21	interface MenuPosition {
22	  top: number;
23	  left: number;
24	  width: number;
25	}
26	
27	export function Dropdown({
28	  options,
29	  value,
30	  onChange,
31	  placeholder = 'Select an option',
32	  label,
33	  className = '',
34	}: DropdownProps) {
35	  const [isOpen, setIsOpen] = useState(false);
36	  const [selectedValue, setSelectedValue] = useState(value || '');
37	  const [menuPosition, setMenuPosition] = useState<MenuPosition | null>(null);
38	  const triggerRef = useRef<HTMLButtonElement>(null);
39	  const menuRef = useRef<HTMLDivElement>(null);
40	
41	  const selectedOption = options.find(
42	    (option) => option.value === selectedValue
43	  );
44	
45	  // Click-outside dismissal — must check both trigger AND portal'd menu since
46	  // the menu is no longer a DOM child of the trigger.
47	  useEffect(() => {
48	    if (!isOpen) return;
49	    const handleClickOutside = (event: MouseEvent) => {
50	      const target = event.target as Node;
51	      if (
52	        triggerRef.current?.contains(target) ||
53	        menuRef.current?.contains(target)
54	      ) {
55	        return;
56	      }
57	      setIsOpen(false);
58	    };
59	    const handleKey = (event: KeyboardEvent) => {
60	      if (event.key === 'Escape') setIsOpen(false);
61	    };
62	
63	    document.addEventListener('mousedown', handleClickOutside);
64	    document.addEventListener('keydown', handleKey);
65	    return () => {
66	      document.removeEventListener('mousedown', handleClickOutside);
67	      document.removeEventListener('keydown', handleKey);
68	    };
69	  }, [isOpen]);
70	
71	  // Position the portal'd menu directly under the trigger using fixed
72	  // coordinates, so it escapes any modal/scroll-container clipping.
73	  // Recompute on scroll/resize while open.
74	  useLayoutEffect(() => {
75	    if (!isOpen) {
76	      setMenuPosition(null);
77	      return;
78	    }
79	    const updatePosition = () => {
80	      const rect = triggerRef.current?.getBoundingClientRect();
81	      if (!rect) return;
82	      setMenuPosition({
83	        top: rect.bottom + 4,
84	        left: rect.left,
85	        width: rect.width,
86	      });
87	    };
88	    updatePosition();
89	    window.addEventListener('resize', updatePosition);
90	    window.addEventListener('scroll', updatePosition, true);
91	    return () => {
92	      window.removeEventListener('resize', updatePosition);
93	      window.removeEventListener('scroll', updatePosition, true);
94	    };
95	  }, [isOpen]);
96	
97	  const handleSelect = (option: DropdownOption) => {
98	    setSelectedValue(option.value);
99	    setIsOpen(false);
100	    onChange?.(option.value, option.key);
101	  };
102	
103	  return (
104	    <div className={`relative ${className}`}>
105	      {label && (
106	        <label className="block text-sm font-medium text-slate-300 mb-2">
107	          {label}
108	        </label>
109	      )}
110	
111	      <button
112	        ref={triggerRef}
113	        type="button"
114	        onClick={() => setIsOpen((current) => !current)}
115	        className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-left text-slate-200 hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-300 ease-in-out flex items-center justify-between"
116	      >
117	        <span className={selectedOption ? 'text-slate-200' : 'text-slate-400'}>
118	          {selectedOption ? selectedOption.label : placeholder}
119	        </span>
120	        <svg
121	          className={`w-5 h-5 text-slate-400 transition-transform duration-300 ease-in-out ${
122	            isOpen ? 'rotate-180' : ''
123	          }`}
124	          fill="none"
125	          stroke="currentColor"
126	          viewBox="0 0 24 24"
127	        >
128	          <path
129	            strokeLinecap="round"
130	            strokeLinejoin="round"
131	            strokeWidth={2}
132	            d="M19 9l-7 7-7-7"
133	          />
134	        </svg>
