1	'use client';
2	
3	// AuthSessionProvider bridges Openfort identity with our app session.
4	//
5	// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
6	// session (JWT + httpOnly refresh cookie), user profile, and the qualification
7	// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
8	// we call create() explicitly at the right moment.
9	//
10	// Status machine:
11	//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
12	//                 ↘ creating_wallet → authenticated   (existing user)
13	//                 ↘ error                             (any failure)
14	//
15	// New-user path (registration):
16	//   Openfort auth → check backend (exists: false) → qualification questionnaire
17	//   → backend exchange with role/type → createWalletIfNeeded → authenticated
18	//
19	// Existing-user path (login):
20	//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
21	//                                        ↘ no cookie → check backend (exists: true)
22	//                                          → backend exchange → createWalletIfNeeded
23	//
24	// createWalletIfNeeded always calls Openfort's create() to load the iframe and
25	// establish the embedded-wallet connection. For new users create() provisions
26	// the wallet; for returning users it reconnects to the existing one. Skipping
27	// this step for returning users leaves the wallet in [Not connected] state
28	// because the embedded-wallet iframe is never loaded (connectOnLogin: false).
29	
30	import type { User } from '@openfort/openfort-js';
31	import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
32	import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
33	import {
34	  checkOpenfortUser,
35	  deleteBackendAccount,
36	  exchangeOpenfortSession,
37	  getBackendMe,
38	  logoutBackendSession,
39	  refreshBackendSession,
40	  type BackendMeResponse,
41	} from '@/lib/backend-auth-client';
42	import {
43	  QualificationQuestionnaire,
44	  type QualificationSubmission,
45	} from './qualification-questionnaire';
46	import {
47	  createContext,
48	  useCallback,
49	  useContext,
50	  useEffect,
51	  useMemo,
52	  useRef,
53	  useState,
54	  type ReactNode,
55	} from 'react';
56	import { usePathname } from 'next/navigation';
57	import { reportError } from '@/lib/error-reporting';
58	
59	type AppSessionStatus =
60	  | 'idle'
61	  | 'loading'
62	  | 'needs_onboarding'
63	  | 'creating_wallet'
64	  | 'authenticated'
65	  | 'unauthenticated'
66	  | 'error';
67	
68	type ErrorCategory = 'recoverable' | 'fatal';
69	
70	type AuthStepId =
71	  | 'signing_in'
72	  | 'checking_account'
73	  | 'restoring_session'
74	  | 'creating_account'
75	  | 'loading_profile'
76	  | 'connecting_wallet'
77	  | 'setting_up_wallet';
78	
79	type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';
80	
81	export interface AuthProgressStep {
82	  id: AuthStepId;
83	  label: string;
84	  status: AuthStepStatus;
85	  errorMessage?: string;
86	}
87	
88	interface AuthProgress {
89	  steps: AuthProgressStep[];
90	  isVisible: boolean;
91	}
92	
93	const STEP_LABELS: Record<AuthStepId, string> = {
94	  signing_in: 'Authenticating with Openfort',
95	  checking_account: 'Checking your account',
96	  restoring_session: 'Restoring your session',
97	  creating_account: 'Creating your account',
98	  loading_profile: 'Loading your profile',
99	  connecting_wallet: 'Connecting your wallet',
100	  setting_up_wallet: 'Setting up your wallet',
101	};
102	
103	interface AuthSessionContextValue {
104	  status: AppSessionStatus;
105	  backendAccessToken: string | null;
106	  backendUser: BackendMeResponse | null;
107	  openfortUser: User | null;
108	  isOpenfortLoading: boolean;
109	  isOpenfortAuthenticated: boolean;
110	  error: string | null;
111	  errorCategory: ErrorCategory | null;
112	  retry: () => void;
113	  deleteAccount: () => Promise<void>;
114	  logout: () => Promise<void>;
115	  authProgress: AuthProgress | null;
116	  dismissProgress: () => void;
117	  cancelAuthFlow: () => Promise<void>;
118	}
119	
120	const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
121	const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';
122	
123	function getErrorMessage(error: unknown) {
124	  if (error instanceof Error && error.message) {
125	    return error.message;
126	  }
127	
128	  if (typeof error === 'string' && error) {
129	    return error;
130	  }
131	
132	  if (error && typeof error === 'object') {
133	    if (
134	      'message' in error &&
135	      typeof error.message === 'string' &&
136	      error.message
137	    ) {
138	      return error.message;
139	    }
140	
141	    try {
142	      return JSON.stringify(error);
143	    } catch {}
144	  }
145	
146	  return 'Failed to initialize your session.';
147	}
148	
149	function getUserFacingErrorMessage(message: string) {
150	  if (/failed to establish iFrame connection/i.test(message)) {
151	    return "We couldn't connect to the wallet service. Please check your connection and try again.";
152	  }
153	
154	  if (
155	    /openfort shield rejected the wallet setup request|failed to create account or device|a_invalid|invalid token/i.test(
156	      message
157	    )
158	  ) {
159	    return 'Wallet setup is currently misconfigured on the server. Request Admin to check SHIELD env var settings; retrying will not fix it.';
160	  }
161	
162	  if (
163	    /next_public_shield_api_key|shield_secret_key|shield_encryption_share/i.test(
164	      message
165	    )
166	  ) {
167	    return 'Wallet setup is unavailable because a required Openfort Shield configuration value is missing or invalid. Request Admin to check SHIELD env var settings.';
168	  }
169	
170	  if (
171	    /user type is required|user role is required|organization name is required/i.test(
172	      message
173	    )
174	  ) {
175	    return `Account setup is missing required onboarding data. ${message}`;
176	  }
177	
178	  if (/openfort access token is unavailable/i.test(message)) {
179	    return 'Your Openfort sign-in session is missing or expired. Please sign in again.';
180	  }
181	
182	  if (
183	    /not logged in|session expired|invalid openfort access token/i.test(message)
184	  ) {
185	    return 'Your session expired. Please sign in again.';
186	  }
187	
188	  if (/failed to fetch|networkerror/i.test(message)) {
189	    return 'We hit a network issue. Please try again.';
190	  }
191	
192	  if (/internal server error/i.test(message)) {
193	    return 'Our service is temporarily unavailable. Please try again in a moment.';
194	  }
195	
196	  if (message && message !== 'Failed to initialize your session.') {
197	    return message;
198	  }
199	
200	  return 'Something went wrong. Please try again.';
201	}
202	
203	function classifyError(message: string): ErrorCategory {
204	  if (
205	    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
206	      message
207	    )
208	  ) {
209	    return 'recoverable';
210	  }
211	
212	  return 'fatal';
213	}
214	
215	function clearOnboardingDraft() {
216	  if (typeof window !== 'undefined') {
217	    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
218	  }
219	}
220	
221	export function AuthSessionProvider({ children }: { children: ReactNode }) {
222	  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
223	  const { signOut } = useSignOut();
224	  const { close: closeOpenfortModal } = useUI();
225	  const { create, wallets } = useEthereumEmbeddedWallet();
226	  const openfortUserId = user?.id ?? null;
227	  const [status, setStatus] = useState<AppSessionStatus>('idle');
228	  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
229	    null
230	  );
231	  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
232	    null
233	  );
234	  const [error, setError] = useState<string | null>(null);
235	  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
236	    null
237	  );
238	  const [retryCount, setRetryCount] = useState(0);
239	  const pathname = usePathname();
240	  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
241	    useState<string | null>(null);
242	  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
243	    accessToken: string;
244	    user: BackendMeResponse;
245	    walletStepId: 'connecting_wallet' | 'setting_up_wallet';
246	  } | null>(null);
247	  const previousAuthState = useRef(false);
248	  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
249	  // This prevents the useEffect from re-triggering bootstrap when callbacks are
250	  // recreated due to dependency changes mid-flow.
251	  const bootstrapAttemptKeyRef = useRef<string | null>(null);
252	  const [authProgress, setAuthProgress] = useState<AuthProgress | null>(null);
253	
254	  const setStepPlan = useCallback((stepIds: AuthStepId[]) => {
255	    setAuthProgress({
256	      isVisible: true,
257	      steps: stepIds.map((id) => ({
258	        id,
259	        label: STEP_LABELS[id],
260	        status: 'pending',
261	      })),
262	    });
263	  }, []);
264	
265	  const updateStep = useCallback(
266	    (id: AuthStepId, patch: Partial<AuthProgressStep>) => {
267	      setAuthProgress((current) => {
268	        if (!current) return current;
269	        const steps = current.steps.map((step) =>
270	          step.id === id ? { ...step, ...patch } : step
271	        );
272	        return { ...current, steps };
273	      });
274	    },
275	    []
