    if (!address) return;
    try {
      await navigator.clipboard.writeText(address);
      setJustCopied(true);
      window.setTimeout(() => setJustCopied(false), 1500);
    } catch {
      // Clipboard API can fail in non-secure contexts; ignore silently.
    }
  };

  const handleAccount = () => {
    setIsOpen(false);
    router.push('/account');
